{
  "name": "opencode-usage-widget",
  "version": "0.1.2",
  "description": "TUI plugin that shows OpenCode Go plan usage (rolling/weekly/monthly) in the sidebar",
  "type": "module",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/crayonxiaoxin/opencode-go-usage.git"
  },
  "bugs": {
    "url": "https://github.com/crayonxiaoxin/opencode-go-usage/issues"
  },
  "homepage": "https://github.com/crayonxiaoxin/opencode-go-usage#readme",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "usage",
    "quota"
  ],
  "files": ["dist", "screenshot.png", "logo.png"],
  "exports": {
    "./tui": {
      "import": "./dist/tui.js"
    }
  },
  "engines": {
    "opencode": ">=1.18.0"
  },
  "peerDependencies": {
    "@opentui/core": "*",
    "@opentui/solid": "*",
    "solid-js": "*"
  },
  "scripts": {
    "build": "node build.tui.mjs",
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "bun test && bun run typecheck && bun run build"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.4.11",
    "@opentui/core": "*",
    "@opentui/solid": "*",
    "@types/bun": "1.1.18",
    "esbuild": "^0.25.0",
    "esbuild-plugin-solid": "^0.6.0",
    "solid-js": "*",
    "typescript": "*"
  }
}
